        long completionRate = pastNonCancelled == 0
                ? 0
                : Math.round((completedPast * 100.0) / pastNonCancelled);

        return new DoctorWorkloadStatsDto(
                doctorId,
                todayCount,
                upcomingCount,
                totalPatients,
                completionRate
        );
    }

